mapper.insert:
INSERT OR IGNORE INTO pet_assets (
    account_id, bones, food, makeup_cards, dog_slots, energy_limit, companion_dog_id, created_at, updated_at
) VALUES (
    #{accountId}, #{bones}, #{food}, #{makeupCards}, #{dogSlots}, #{energyLimit}, #{companionDogId},
    #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE pet_assets
SET food = food - 1,
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND food > 0

UPDATE pet_assets
SET makeup_cards = makeup_cards - 1,
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND makeup_cards > 0

UPDATE pet_assets
SET bones = bones - #{price},
    dog_slots = dog_slots + 1,
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND dog_slots < 2
  AND bones >= #{price}

UPDATE pet_assets
SET bones = bones - #{price},
    food = food + #{quantity},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND bones >= #{price}
  AND food + #{quantity} <= #{maxFood}

UPDATE pet_assets
SET bones = bones - #{price},
    makeup_cards = makeup_cards + #{quantity},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND bones >= #{price}
  AND makeup_cards + #{quantity} <= #{maxMakeupCards}

UPDATE pet_assets
SET bones = bones - #{amount},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND bones >= #{amount}

UPDATE pet_assets
SET companion_dog_id = #{companionDogId},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}

UPDATE pet_assets
SET bones = bones + #{amount},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}

UPDATE pet_assets
SET food = food + #{amount},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
